export const messages=Object.fromEntries(['en','zh','ja','de'].map((locale,index)=>[locale,Object.fromEntries(Object.entries(copy).map(([key,values])=>[key,values[index]]))]));
export const normalizeLanguage=value=>['system','zh','en','ja','de'].includes(value)?value:'system';
export function resolveLocale(language='system',languages=globalThis.navigator?.languages??[globalThis.navigator?.language??'en']){
  if(normalizeLanguage(language)!=='system')return language;
  for(const candidate of languages){const base=String(candidate).toLowerCase().split(/[-_]/)[0];if(messages[base])return base;}
  return 'en';
}
export function createI18n({language='system',languages=()=>globalThis.navigator?.languages??[globalThis.navigator?.language??'en'],document=null}={}){
  let selected=normalizeLanguage(language);const listeners=new Set();
  const api={
    get language(){return selected;},
    get locale(){return resolveLocale(selected,typeof languages==='function'?languages():languages);},
    t(key,values={}){return(messages[api.locale][key]??messages.en[key]??key).replace(/\{(\w+)\}/g,(match,name)=>values[name]===undefined?match:String(values[name]));},
    text(node,key,values={}){if(!node)return;node.dataset.i18n=key;node.dataset.i18nValues=JSON.stringify(values);node.textContent=api.t(key,values);},
    attribute(node,name,key,values={}){if(!node)return;node.dataset['i18n'+name.replace(/(^|-)(\w)/g,(_,dash,char)=>char.toUpperCase())]=key;node.setAttribute(name,api.t(key,values));},
    apply(root=document){
      if(!root)return;
      if(root.documentElement)root.documentElement.lang=api.locale==='zh'?'zh-CN':api.locale;
      for(const node of root.querySelectorAll('[data-i18n]'))node.textContent=api.t(node.dataset.i18n,JSON.parse(node.dataset.i18nValues??'{}'));
      for(const name of ['placeholder','title','aria-label'])for(const node of root.querySelectorAll('[data-i18n-'+name+']'))node.setAttribute(name,api.t(node.getAttribute('data-i18n-'+name)));
    },
    setLanguage(value){selected=normalizeLanguage(value);api.refresh();},
    refresh(){api.apply();for(const listener of listeners)listener();},
    subscribe(listener){listeners.add(listener);return()=>listeners.delete(listener);},
    error(error){
      const value=String(error?.message??error??'');
      const rules=[
        [/NEARCAST_KEY_MISMATCH/,'pair.changed'],
        [/无法完成设备连接/,'error.pairing'],
        [/4 位字母|four letters|Pairing code must/i,'error.code'],
        [/发现已过期|discovery expired/i,'error.expired'],
        [/当前连接方式的配对码/,'error.route'],
        [/局域网投屏.*先.*选择.*接收端/i,'error.localSelect'],
        [/不支持局域网直连|does not support local signaling/i,'error.localUnsupported'],
        [/local.*unavailable|本地.*(不可用|尚未就绪)|无法连接.*本地信令/i,'error.localUnavailable'],
        [/cloud.*unavailable|云端.*不可用/i,'error.cloudUnavailable'],
        [/room.*closed|关闭投屏房间/i,'error.roomClosed'],
        [/ended.*connection|结束.*连接|结束本次投屏/i,'error.peerLeft'],
        [/pairing code rejected|配对码.*(错误|过期)|invalid.*code/i,'error.rejected'],
        [/WebSocket|WebRTC connection failed|信令连接已关闭/,'error.network'],
        [/屏幕录制|macOS.*屏幕分享需要/,'error.capturePermission'],
        [/(screen capture|display video track).*unavailable|WebView.*不提供屏幕/i,'error.captureUnavailable'],
        [/NotAllowedError|cancelled by user/i,'error.captureCancelled'],
        [/完成或取消.*选择/,'error.pickerPending'],
        [/输入尚未释放/,'error.cleanup'],
      ];
      const key=rules.find(([pattern])=>pattern.test(value))?.[1];return key?api.t(key):value;
    },
  };
  return api;
}
export const i18n=createI18n({document:globalThis.document});
globalThis.addEventListener?.('languagechange',()=>{if(i18n.language==='system')i18n.refresh();});
